python3 - <<'EOF'
import json,urllib.request
hdr={'User-Agent':'Mozilla/5.0'}
url='https://omgithub.com/api/projects?limit=100'
seen=[]
try:
  for i in range(50):
    req=urllib.request.Request(url,headers=hdr)
    d=json.load(urllib.request.urlopen(req))
    seen+=d['projects']
    c=d.get('next_cursor')
    if not c: break
    url=f'https://omgithub.com/api/projects?limit=100&cursor={c}'
  print('total fetched',len(seen))
  for p in seen:
    if 'arken' in (p['title']+' '+p['description']+' '+p['repo']+' '+p['repo_owner']).lower():
        print(p['title'],p['repo_owner'],p['repo'],p['url'])
except Exception as e:
  print('ERR',e,'fetched',len(seen))
EOF

