:root {
  --ink: #0a0f12;
  --ink-2: #111a1e;
  --panel: rgba(13, 20, 24, 0.9);
  --panel-solid: #111b20;
  --panel-hi: #17262c;
  --line: rgba(240, 219, 174, 0.16);
  --line-strong: rgba(240, 219, 174, 0.32);
  --parchment: #f2e4c4;
  --muted: #9aacaa;
  --faint: #6c7d7c;
  --ember: #ff9f43;
  --ember-hot: #ffd27a;
  --ember-deep: #b95722;
  --teal: #5fd0b4;
  --blood: #e05d5d;
  --gold: #f2c45c;
  --xp: #7db6ff;
  --safe-b: env(safe-area-inset-bottom, 0px);
  --safe-t: env(safe-area-inset-top, 0px);
  --safe-l: env(safe-area-inset-left, 0px);
  --safe-r: env(safe-area-inset-right, 0px);
  --serif: "Iowan Old Style", "Palatino Linotype", Palatino, Georgia, serif;
  --mono: "SFMono-Regular", "Cascadia Mono", "Roboto Mono", Menlo, Consolas, monospace;
}

* { box-sizing: border-box; }
[hidden] { display: none !important; }
html, body {
  margin: 0;
  padding: 0;
  width: 100%;
  height: 100%;
  overflow: hidden;
  background: var(--ink);
  color: var(--parchment);
  font-family: var(--mono);
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
  overscroll-behavior: none;
}
body {
  position: fixed;
  inset: 0;
  touch-action: none;
  -webkit-user-select: none;
  user-select: none;
  -webkit-tap-highlight-color: transparent;
}
button, select, input { font: inherit; color: inherit; }
button { cursor: pointer; }
svg { display: block; width: 1em; height: 1em; fill: currentColor; }
.icon-defs { position: absolute; width: 0; height: 0; overflow: hidden; }
#app { position: absolute; inset: 0; }

#game {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
  image-rendering: pixelated;
  image-rendering: crisp-edges;
  background: #0b1114;
  outline: none;
}
#vignette {
  position: absolute;
  inset: 0;
  pointer-events: none;
  background:
    radial-gradient(120% 90% at 50% 48%, transparent 52%, rgba(3, 7, 9, 0.42) 100%),
    linear-gradient(to bottom, rgba(3, 7, 9, 0.3), transparent 13%, transparent 82%, rgba(3, 7, 9, 0.4));
  z-index: 2;
}

/* ---------- shared pieces ---------- */
.panel {
  background: var(--panel);
  border: 1px solid var(--line);
  border-radius: 8px;
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.24);
}
.coin {
  width: 10px; height: 10px; display: inline-block; border-radius: 50%;
  background: radial-gradient(circle at 35% 30%, #fff2b3, var(--gold) 55%, #9d6b1d);
  box-shadow: 0 0 6px rgba(242, 196, 92, 0.35);
  vertical-align: -1px;
}
.eyebrow, .dialog-kicker, .quest-kicker {
  font-size: 9px;
  letter-spacing: 0.22em;
  text-transform: uppercase;
  color: var(--ember);
  font-weight: 700;
}
kbd {
  font-family: var(--mono);
  font-size: 8px;
  line-height: 1;
  padding: 2px 4px;
  border-radius: 3px;
  color: rgba(242, 228, 196, 0.62);
  background: rgba(0, 0, 0, 0.28);
  border: 1px solid rgba(255, 255, 255, 0.07);
}
.round-btn {
  width: 38px; height: 38px; border-radius: 50%;
  display: grid; place-items: center;
  border: 1px solid var(--line);
  background: var(--panel);
  color: var(--parchment);
  font-size: 17px;
  transition: background .15s, border-color .15s, transform .1s;
}
.round-btn:hover { background: var(--panel-hi); border-color: var(--line-strong); }
.round-btn:active { transform: scale(0.94); }
.round-btn svg { width: 17px; height: 17px; }
.primary-btn, .secondary-btn, .danger-btn {
  display: block; width: 100%;
  border-radius: 8px;
  padding: 15px 20px;
  font-weight: 800;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  font-size: 13px;
  border: 1px solid transparent;
  transition: transform .12s, filter .15s, background .15s;
}
.primary-btn {
  color: #1a1007;
  background: linear-gradient(180deg, var(--ember-hot), var(--ember) 55%, #e07e29);
  box-shadow: 0 8px 24px rgba(255, 147, 51, 0.22), inset 0 1px 0 rgba(255,255,255,.45);
  border-color: #ffc36a;
}
.primary-btn:hover { filter: brightness(1.07); }
.primary-btn:active { transform: translateY(1px) scale(0.995); }
.secondary-btn {
  color: var(--parchment);
  background: rgba(95, 208, 180, 0.08);
  border-color: rgba(95, 208, 180, 0.32);
}
.secondary-btn:hover { background: rgba(95, 208, 180, 0.15); }
.danger-btn {
  color: #ffb2a8;
  background: rgba(224, 93, 93, 0.06);
  border-color: rgba(224, 93, 93, 0.28);
}
.danger-btn:hover { background: rgba(224, 93, 93, 0.13); }
.text-btn {
  background: none; border: 0; padding: 8px 2px;
  color: var(--muted); font-size: 10px; letter-spacing: .14em;
  text-transform: uppercase; text-decoration: underline;
  text-decoration-color: rgba(154, 172, 170, 0.35);
  text-underline-offset: 4px;
}
.text-btn:hover { color: var(--ember-hot); }
button:focus-visible, select:focus-visible, input:focus-visible {
  outline: 2px solid var(--ember);
  outline-offset: 3px;
}

/* ---------- HUD ---------- */
#hud { position: absolute; inset: 0; z-index: 5; pointer-events: none; }
#hud button, #hud select { pointer-events: auto; }
.hud-top {
  position: absolute;
  top: calc(8px + var(--safe-t));
  left: calc(8px + var(--safe-l));
  right: calc(8px + var(--safe-r));
  display: flex; align-items: flex-start; justify-content: space-between; gap: 8px;
}
.status-panel {
  display: flex; gap: 8px; align-items: center;
  padding: 7px 10px 7px 7px;
  min-width: 210px;
}
.level-badge {
  flex: 0 0 auto;
  width: 42px; height: 42px; border-radius: 6px;
  display: grid; place-items: center;
  font-family: var(--serif); font-size: 21px; font-weight: 800;
  color: var(--ember-hot);
  background: linear-gradient(160deg, #2a2018, #14100d);
  border: 1px solid rgba(255, 177, 92, 0.4);
  box-shadow: inset 0 0 12px rgba(255, 147, 51, 0.12);
}
.status-bars { flex: 1; display: grid; gap: 4px; min-width: 0; }
.bar {
  position: relative; height: 13px; border-radius: 3px; overflow: hidden;
  background: rgba(0, 0, 0, 0.46);
  border: 1px solid rgba(255, 255, 255, 0.07);
}
.bar i {
  position: absolute; inset: 0; transform-origin: left center;
  display: block; border-radius: 2px;
}
.bar span {
  position: absolute; inset: 0; display: grid; place-items: center;
  font-size: 8px; letter-spacing: .04em; font-weight: 700;
  color: #fdf6e6; text-shadow: 0 1px 2px rgba(0,0,0,.8);
}
.bar.hp i { background: linear-gradient(90deg, #8f2f32, var(--blood) 65%, #ff8b80); width: 100%; }
.bar.mp i { background: linear-gradient(90deg, #235a80, #4b9ed1 65%, #8bd3ff); width: 100%; }
.bar.xp { height: 8px; }
.bar.xp i { background: linear-gradient(90deg, #355d9c, var(--xp)); width: 0%; }
.bar.xp span { font-size: 7px; color: rgba(242,228,196,.72); }
.bar.boss { height: 10px; border-color: rgba(255, 177, 92, 0.25); }
.bar.boss i { width: 100%; background: linear-gradient(90deg, #782424, #e05d5d 55%, #ffb15c); }
.hud-actions { display: flex; align-items: center; gap: 6px; }
.gold-pill {
  display: flex; align-items: center; gap: 6px;
  padding: 8px 11px; border-radius: 999px;
  font-size: 11px; color: var(--gold); min-height: 38px;
}
.gold-pill b { color: var(--parchment); font-weight: 700; }
#quest-tracker {
  position: absolute;
  top: calc(66px + var(--safe-t));
  left: calc(8px + var(--safe-l));
  width: min(280px, calc(100vw - 92px));
  padding: 9px 11px;
  border-left: 2px solid var(--ember);
  pointer-events: none;
}
.quest-line { display: flex; align-items: center; gap: 6px; margin: 3px 0 2px; min-width: 0; }
.quest-line b { font-family: var(--serif); font-size: 14px; color: var(--parchment); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.quest-arrow { display: inline-flex; color: var(--ember); font-size: 12px; transform-origin: center; }
.quest-arrow svg { width: 12px; height: 12px; }
#quest-dist { margin-left: auto; font-size: 9px; color: var(--muted); white-space: nowrap; }
#quest-objective { font-size: 9px; line-height: 1.45; color: var(--muted); }
#quest-objective progress { width: 100%; height: 4px; margin-top: 4px; }
.boss-bar {
  position: absolute; top: calc(72px + var(--safe-t)); left: 50%; transform: translateX(-50%);
  width: min(420px, calc(100vw - 48px)); padding: 8px 11px;
  background: var(--panel); border: 1px solid rgba(224, 93, 93, 0.32); border-radius: 7px;
  pointer-events: none;
}
.boss-name { font-family: var(--serif); font-size: 13px; color: #ffc1a1; text-align: center; margin-bottom: 5px; letter-spacing: .06em; }
.region-banner {
  position: absolute; top: 27%; left: 50%; transform: translate(-50%, -50%) scale(.97);
  font-family: var(--serif); font-size: clamp(18px, 3.6vw, 30px); letter-spacing: .22em;
  color: rgba(242, 228, 196, .88); text-shadow: 0 2px 18px rgba(0,0,0,.85);
  opacity: 0; transition: opacity .5s, transform .5s; pointer-events: none; white-space: nowrap;
  text-transform: uppercase;
}
.region-banner.show { opacity: 1; transform: translate(-50%, -50%) scale(1); }
#toasts {
  position: absolute; top: calc(112px + var(--safe-t)); left: 50%; transform: translateX(-50%);
  width: min(340px, calc(100vw - 28px)); display: grid; gap: 5px; pointer-events: none;
}
.toast {
  align-self: start; justify-self: center; max-width: 100%;
  padding: 7px 10px; border-radius: 5px;
  background: rgba(10, 16, 18, .92); border: 1px solid var(--line);
  font-size: 10px; line-height: 1.35; color: var(--parchment);
  box-shadow: 0 4px 16px rgba(0,0,0,.25);
  animation: toastIn .18s ease-out both;
}
.toast.gold { border-color: rgba(242,196,92,.35); color: var(--gold); }
.toast.good { border-color: rgba(95,208,180,.35); color: #b9f5e5; }
.toast.bad { border-color: rgba(224,93,93,.35); color: #ffc0b8; }
.toast.quest { border-color: rgba(255,159,67,.45); color: var(--ember-hot); }
.toast.out { animation: toastOut .22s ease-in both; }
@keyframes toastIn { from { opacity: 0; transform: translateY(-5px); } }
@keyframes toastOut { to { opacity: 0; transform: translateY(-4px); } }
.level-banner {
  position: absolute; top: 38%; left: 50%; transform: translate(-50%, -50%);
  font-family: var(--serif); font-size: clamp(22px, 5vw, 40px); letter-spacing: .3em;
  color: var(--ember-hot); text-shadow: 0 0 26px rgba(255,159,67,.6);
  animation: levelPulse 1.7s ease-out both; pointer-events: none;
}
@keyframes levelPulse {
  0% { opacity: 0; transform: translate(-50%, -50%) scale(.7); }
  18% { opacity: 1; transform: translate(-50%, -50%) scale(1.04); }
  72% { opacity: 1; }
  100% { opacity: 0; transform: translate(-50%, -58%) scale(1); }
}
#interact-prompt {
  position: absolute; left: 50%; bottom: calc(150px + var(--safe-b)); transform: translateX(-50%);
  pointer-events: auto; z-index: 7;
}
.interact-btn {
  display: flex; align-items: center; gap: 8px;
  padding: 9px 14px; border-radius: 999px;
  background: rgba(10, 16, 18, .94); border: 1px solid rgba(255,159,67,.45);
  color: var(--parchment); font-size: 11px; font-weight: 700; letter-spacing: .06em;
  box-shadow: 0 4px 20px rgba(0,0,0,.35);
}
.interact-btn svg { color: var(--ember); width: 14px; height: 14px; }
.interact-btn kbd { margin-left: 2px; }
#fps {
  position: absolute; right: calc(10px + var(--safe-r)); bottom: calc(10px + var(--safe-b));
  font-size: 9px; color: var(--faint); background: rgba(0,0,0,.4); padding: 4px 6px; border-radius: 3px;
}

/* ---------- touch controls ---------- */
#controls { position: absolute; inset: 0; pointer-events: none; z-index: 6; }
#joystick {
  position: absolute; left: calc(20px + var(--safe-l)); bottom: calc(22px + var(--safe-b));
  width: 116px; height: 116px; border-radius: 50%;
  pointer-events: auto; touch-action: none;
}
.stick-base {
  position: absolute; inset: 0; border-radius: 50%;
  background: radial-gradient(circle, rgba(23,38,44,.72), rgba(10,16,18,.58));
  border: 1px solid rgba(242,228,196,.18);
  box-shadow: inset 0 0 22px rgba(0,0,0,.4);
}
.stick-mark { position: absolute; left: 50%; transform: translateX(-50%); font-size: 8px; color: rgba(242,228,196,.26); }
.stick-mark.n { top: 8px; } .stick-mark.s { bottom: 8px; }
#joystick-knob {
  position: absolute; left: 50%; top: 50%; width: 48px; height: 48px; margin: -24px 0 0 -24px;
  border-radius: 50%;
  background: radial-gradient(circle at 38% 30%, #f7d9a2, #c9833b 58%, #75401b);
  border: 1px solid rgba(255, 219, 158, .55);
  box-shadow: 0 4px 14px rgba(0,0,0,.36), inset 0 1px 2px rgba(255,255,255,.4);
  will-change: transform;
}
#action-cluster {
  position: absolute; right: calc(16px + var(--safe-r)); bottom: calc(16px + var(--safe-b));
  width: 176px; height: 176px; pointer-events: none;
}
.action {
  position: absolute; pointer-events: auto; touch-action: none;
  display: grid; place-items: center;
  border-radius: 50%; border: 1px solid var(--line-strong);
  background: radial-gradient(circle at 38% 30%, rgba(32, 48, 54, .95), rgba(10, 16, 18, .94));
  color: var(--parchment);
  box-shadow: 0 5px 18px rgba(0,0,0,.3);
  transition: transform .08s, filter .12s;
}
.action:active, .action.down { transform: scale(.93); filter: brightness(1.15); }
.action svg { width: 24px; height: 24px; }
.action.attack { right: 0; bottom: 0; width: 84px; height: 84px; border-color: rgba(255,159,67,.46); color: var(--ember-hot); }
.action.attack svg { width: 36px; height: 36px; }
.action.attack::after { content: ""; position: absolute; inset: -5px; border-radius: 50%; border: 1px solid rgba(255,159,67,.18); }
.action.ember { right: 92px; bottom: 12px; width: 60px; height: 60px; color: #ffb469; }
.action.mend { right: 76px; bottom: 82px; width: 56px; height: 56px; color: #9ce6c9; }
.action.potion { right: 8px; bottom: 94px; width: 52px; height: 52px; color: #ffb0a8; }
.action .badge {
  position: absolute; top: -1px; right: -1px; min-width: 18px; height: 18px; padding: 0 4px;
  display: grid; place-items: center; border-radius: 999px;
  background: #2a1a12; border: 1px solid rgba(242,196,92,.5); color: var(--gold);
  font-size: 9px; font-weight: 700;
}
.action kbd { position: absolute; bottom: -3px; right: 4px; opacity: .5; font-size: 7px; }
.action.attack kbd { bottom: 8px; right: 15px; }
#desktop-hint {
  position: absolute; left: calc(16px + var(--safe-l)); bottom: calc(14px + var(--safe-b));
  font-size: 8px; line-height: 1.5; color: rgba(154,172,170,.55);
  max-width: 340px; letter-spacing: .03em;
}
@media (pointer: coarse) { #desktop-hint { display: none; } }
@media (max-width: 900px) { #desktop-hint { display: none; } }
@media (min-width: 901px) and (pointer: fine) {
  #joystick { display: none; }
  #action-cluster { right: 24px; bottom: 24px; }
}

/* ---------- overlays ---------- */
.overlay {
  position: absolute; inset: 0; z-index: 20;
  display: flex; align-items: center; justify-content: center;
  padding: calc(16px + var(--safe-t)) calc(16px + var(--safe-r)) calc(16px + var(--safe-b)) calc(16px + var(--safe-l));
  background: rgba(4, 8, 10, .68);
}
.title-screen {
  background:
    radial-gradient(80% 60% at 50% 38%, rgba(255, 147, 51, .1), transparent 65%),
    linear-gradient(to bottom, rgba(4, 8, 10, .42), rgba(4, 8, 10, .9) 72%);
  overflow: hidden;
}
.start-card {
  position: relative; z-index: 2; width: min(440px, 100%);
  text-align: center; padding: 20px 18px 24px;
}
.brand { position: relative; margin-top: 4vh; }
.brand h1 {
  margin: 4px 0 -2px;
  font-family: var(--serif); font-weight: 900;
  font-size: clamp(42px, 11vw, 72px);
  letter-spacing: .055em; line-height: .95;
  color: #f8ead0;
  text-shadow: 0 2px 0 #6f3a1d, 0 0 34px rgba(255, 147, 51, .24), 0 8px 30px rgba(0,0,0,.55);
}
.brand h1::first-letter { color: var(--ember-hot); }
.subtitle {
  display: flex; align-items: center; gap: 12px; justify-content: center;
  color: var(--ember); font-size: clamp(11px, 2.8vw, 15px); letter-spacing: .52em; font-weight: 700;
  margin: 8px 0 0;
}
.subtitle::before, .subtitle::after {
  content: ""; height: 1px; width: 34px;
  background: linear-gradient(90deg, transparent, rgba(255,159,67,.55));
}
.subtitle::after { transform: scaleX(-1); }
.tagline {
  margin: 24px 0 8px;
  font-family: var(--serif); font-size: clamp(14px, 3.4vw, 18px); color: var(--parchment);
}
.blurb {
  margin: 0 auto 20px; max-width: 360px;
  font-size: 10px; line-height: 1.65; color: var(--muted);
}
.save-summary {
  margin: 12px 0 0; font-size: 9px; letter-spacing: .09em; color: var(--teal);
  text-transform: uppercase;
}
.feature-chips {
  display: flex; flex-wrap: wrap; gap: 5px; justify-content: center; margin: 18px 0 12px;
}
.feature-chips span {
  font-size: 8px; letter-spacing: .13em; text-transform: uppercase;
  color: rgba(242,228,196,.66); padding: 4px 7px; border-radius: 999px;
  border: 1px solid rgba(242,228,196,.14); background: rgba(255,255,255,.02);
}
.lowend-note {
  font-size: 8px; line-height: 1.6; color: var(--faint); max-width: 350px; margin: 0 auto;
}
.start-links { display: flex; justify-content: center; gap: 22px; margin: 13px 0 2px; }
.controls-note { font-size: 8px; line-height: 1.5; color: rgba(154,172,170,.5); margin: 6px 0 0; }
.embers { position: absolute; inset: 0; pointer-events: none; overflow: hidden; }
.embers i {
  position: absolute; bottom: -10px; width: 3px; height: 3px; border-radius: 50%;
  background: var(--ember-hot); box-shadow: 0 0 8px 2px rgba(255,147,51,.35);
  opacity: 0; animation: rise 7s linear infinite;
}
.embers i:nth-child(1) { left: 8%; animation-delay: 0s; }
.embers i:nth-child(2) { left: 20%; animation-delay: 2.2s; animation-duration: 9s; }
.embers i:nth-child(3) { left: 34%; animation-delay: 4.1s; animation-duration: 8s; }
.embers i:nth-child(4) { left: 50%; animation-delay: 1.2s; animation-duration: 10s; }
.embers i:nth-child(5) { left: 66%; animation-delay: 3.4s; animation-duration: 8.5s; }
.embers i:nth-child(6) { left: 79%; animation-delay: 5.3s; animation-duration: 9.5s; }
.embers i:nth-child(7) { left: 91%; animation-delay: 2.8s; animation-duration: 7.5s; }
@keyframes rise {
  0% { opacity: 0; transform: translate3d(0, 0, 0) scale(.7); }
  14% { opacity: .8; }
  80% { opacity: .4; }
  100% { opacity: 0; transform: translate3d(24px, -88vh, 0) scale(1.1); }
}

.sheet-overlay { align-items: flex-end; padding: 0; }
.dialog-sheet, .panel-sheet {
  width: min(560px, 100%);
  background: linear-gradient(180deg, #18252a, #10181c 70%);
  border: 1px solid var(--line-strong); border-bottom: 0;
  border-radius: 14px 14px 0 0;
  padding: 16px 16px calc(16px + var(--safe-b));
  box-shadow: 0 -18px 50px rgba(0,0,0,.45);
  animation: sheetUp .2s ease-out both;
}
@keyframes sheetUp { from { transform: translateY(22px); opacity: .4; } }
.dialog-head, .sheet-head { display: flex; align-items: center; gap: 11px; }
.dialog-head > div, .sheet-head > div { flex: 1; min-width: 0; }
.dialog-head h2, .sheet-head h2 {
  margin: 2px 0 0; font-family: var(--serif); font-size: 23px; line-height: 1.1; color: var(--parchment);
}
#dialog-portrait {
  width: 48px; height: 48px; border-radius: 6px; image-rendering: pixelated;
  background: radial-gradient(circle, #22343a, #0b1114);
  border: 1px solid var(--line);
}
.dialog-text {
  margin: 14px 0 13px; font-size: 11px; line-height: 1.65; color: #d8d2bf;
  min-height: 36px;
}
.dialog-choices { display: grid; gap: 6px; }
.dialog-choice {
  display: flex; align-items: center; gap: 10px; width: 100%;
  padding: 10px 12px; text-align: left; border-radius: 6px;
  background: rgba(255,255,255,.025); border: 1px solid rgba(242,228,196,.13);
  color: var(--parchment); font-size: 10px; line-height: 1.35;
  transition: background .12s, border-color .12s;
}
.dialog-choice:hover { background: rgba(255,159,67,.08); border-color: rgba(255,159,67,.35); }
.dialog-choice:disabled { opacity: .42; cursor: not-allowed; }
.dialog-choice .num {
  flex: 0 0 auto; width: 18px; height: 18px; border-radius: 4px;
  display: grid; place-items: center; font-size: 8px;
  background: rgba(255,159,67,.1); color: var(--ember); border: 1px solid rgba(255,159,67,.24);
}
.dialog-choice .cost { margin-left: auto; color: var(--gold); font-size: 9px; white-space: nowrap; }
.dialog-foot { display: flex; align-items: center; gap: 6px; margin-top: 11px; font-size: 9px; color: var(--muted); }
.dialog-foot b { color: var(--gold); }
.dialog-hint { margin-left: auto; color: var(--faint); font-size: 8px; }

.sheet-overlay { align-items: center; }
.panel-sheet {
  border: 1px solid var(--line-strong); border-radius: 12px; margin: auto;
  max-height: min(86vh, 760px); overflow: auto; padding: 16px;
  box-shadow: 0 18px 60px rgba(0,0,0,.5);
}
.settings-body { display: grid; gap: 8px; margin-top: 16px; }
.setting-row {
  display: flex; align-items: center; justify-content: space-between; gap: 12px;
  padding: 10px 11px; border-radius: 6px;
  background: rgba(255,255,255,.022); border: 1px solid rgba(242,228,196,.1);
  font-size: 10px; letter-spacing: .04em; color: var(--parchment);
}
.setting-row select {
  background: #0d1518; border: 1px solid var(--line); border-radius: 5px;
  padding: 7px 9px; font-size: 10px; color: var(--parchment); min-width: 132px;
}
.setting-row input[type="checkbox"] {
  appearance: none; width: 38px; height: 21px; border-radius: 999px;
  background: #0b1215; border: 1px solid var(--line); position: relative;
}
.setting-row input[type="checkbox"]::after {
  content: ""; position: absolute; top: 2px; left: 2px; width: 15px; height: 15px;
  border-radius: 50%; background: #6f7f7e; transition: transform .16s, background .16s;
}
.setting-row input[type="checkbox"]:checked { background: rgba(255,159,67,.18); border-color: rgba(255,159,67,.45); }
.setting-row input[type="checkbox"]:checked::after { transform: translateX(17px); background: var(--ember-hot); }
.settings-note { font-size: 8px; line-height: 1.6; color: var(--faint); margin: 2px 0 0; }
.stats-body { display: grid; gap: 12px; margin-top: 16px; }
.stat-grid { display: grid; grid-template-columns: repeat(2, 1fr); gap: 6px; }
.stat-box { padding: 9px 10px; border-radius: 6px; background: rgba(255,255,255,.025); border: 1px solid rgba(242,228,196,.1); }
.stat-box span { display: block; font-size: 8px; letter-spacing: .14em; text-transform: uppercase; color: var(--faint); margin-bottom: 3px; }
.stat-box b { font-family: var(--serif); font-size: 16px; font-weight: 600; color: var(--parchment); }
.stat-box b small { font-family: var(--mono); font-size: 8px; color: var(--muted); }
.gear-row { display: flex; align-items: center; gap: 9px; padding: 9px 10px; border-radius: 6px; background: rgba(255,255,255,.025); border: 1px solid rgba(242,228,196,.1); }
.gear-icon { width: 28px; height: 28px; border-radius: 5px; display: grid; place-items: center; background: rgba(255,159,67,.08); color: var(--ember); border: 1px solid rgba(255,159,67,.2); }
.gear-icon svg { width: 15px; height: 15px; }
.gear-row div { flex: 1; min-width: 0; }
.gear-row b { display: block; font-size: 10px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.gear-row span { font-size: 8px; color: var(--muted); }
.stats-sub { font-size: 9px; letter-spacing: .16em; text-transform: uppercase; color: var(--ember); margin: 2px 0 -4px; }
.center-overlay { background: rgba(4, 8, 10, .88); }
.center-card {
  width: min(390px, 100%); text-align: center; padding: 26px 22px;
  background: linear-gradient(180deg, #19262b, #0f171a);
  border: 1px solid var(--line-strong); border-radius: 12px;
  box-shadow: 0 20px 70px rgba(0,0,0,.6);
}
.center-card h2 { margin: 6px 0 10px; font-family: var(--serif); font-size: clamp(25px, 7vw, 34px); line-height: 1.05; color: var(--parchment); }
.center-card p { font-size: 10px; line-height: 1.65; color: var(--muted); margin: 0 0 18px; }
.victory-card { border-color: rgba(255,159,67,.4); box-shadow: 0 0 60px rgba(255,147,51,.12), 0 20px 70px rgba(0,0,0,.6); }
.victory-stats { display: flex; justify-content: center; gap: 20px; margin: 0 0 18px; }
.victory-stats div { font-size: 8px; text-transform: uppercase; letter-spacing: .13em; color: var(--faint); }
.victory-stats b { display: block; font-family: var(--serif); font-size: 20px; color: var(--gold); margin-bottom: 2px; letter-spacing: 0; }
.loading {
  position: absolute; inset: 0; z-index: 50; display: grid; place-items: center;
  background: var(--ink); color: var(--muted); font-size: 10px; letter-spacing: .14em;
  text-transform: uppercase; transition: opacity .3s;
}
.loading span {
  width: 22px; height: 22px; border-radius: 50%; border: 2px solid rgba(255,159,67,.18);
  border-top-color: var(--ember); animation: spin .8s linear infinite; margin-bottom: 8px;
}
@keyframes spin { to { transform: rotate(360deg); } }
.loading.done { opacity: 0; pointer-events: none; }

/* ---------- responsive ---------- */
@media (max-height: 700px) {
  .brand { margin-top: 0; }
  .brand h1 { font-size: clamp(36px, 9vw, 54px); }
  .tagline { margin-top: 14px; }
  .blurb { margin-bottom: 12px; }
  .feature-chips { margin: 12px 0 8px; }
  .lowend-note { display: none; }
  .controls-note { display: none; }
  .start-card { padding-top: 8px; }
}
@media (max-width: 480px) {
  .status-panel { min-width: 0; flex: 1; max-width: 230px; }
  .level-badge { width: 36px; height: 36px; font-size: 18px; }
  .bar { height: 11px; }
  .bar span { font-size: 7px; }
  .gold-pill { padding: 7px 8px; }
  #quest-tracker { top: calc(61px + var(--safe-t)); width: min(248px, calc(100vw - 108px)); }
  #toasts { top: calc(136px + var(--safe-t)); }
  #action-cluster { transform: scale(.92); transform-origin: right bottom; }
  #joystick { transform: scale(.94); transform-origin: left bottom; }
  .dialog-head h2, .sheet-head h2 { font-size: 20px; }
}
@media (max-width: 360px) {
  #action-cluster { transform: scale(.82); }
  #joystick { transform: scale(.86); }
  .hud-actions { gap: 4px; }
  .round-btn { width: 34px; height: 34px; }
  .gold-pill { min-height: 34px; }
}
@media (max-height: 520px) and (orientation: landscape) {
  #quest-tracker { top: calc(59px + var(--safe-t)); width: 220px; }
  #action-cluster { transform: scale(.78); }
  #joystick { transform: scale(.8); }
  #interact-prompt { bottom: calc(88px + var(--safe-b)); }
  .brand h1 { font-size: 40px; }
  .brand { margin-top: 0; }
  .blurb, .lowend-note, .feature-chips, .controls-note { display: none; }
}
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { animation-duration: .001ms !important; animation-iteration-count: 1 !important; transition-duration: .001ms !important; }
}

