function updateAmbient(dt) {
  // Title-screen ambience only: fireflies over the plaza.
  if (Math.random() < dt * 2 && game.particles.length < 10) {
    addParticle({
      x: game.player.x + rand(-70, 70), y: game.player.y + rand(-45, 45),
