+}
+
+

input.newString:
  if (settings.showFps) {
    dom.fps.hidden = false;
    setText(dom.fps, `${Math.round(fps.value)} FPS · ${quality.label}${settings.quality === 'auto' ? ` · ${Math.round(autoScale * 100)}%` : ''}`);
  } else {
